#include <iostream>
#include <vector>
#include <cstring>
#include <cstdio>
#include <climits>
#include <algorithm>
using namespace std;

void calculateMax(int n, vector<vector<int>>& y, vector<vector<int>>& x) {
    vector<vector<int>> mp(n, vector<int>(n));
    for(int i = 0; i < n; i++)
        for(int j = 0; j < n; j++) {
            mp[i][j] = x[i][j] = y[i][j];
        }

    int ans = max(y[0][n - 1], y[n - 1][0]);
    for(int i = 0; i < n; i++) {
        for(int j = n - 2; j >= 0; j--) {
            x[i][j] += x[i][j + 1];
            y[j][i] += y[j + 1][i];
            ans = max(ans, max(x[i][j], y[j][i]));
        }
    }

    // Additional optimization logic
    vector<vector<int>> sum(n + 1, vector<int>(n + 1, INT_MIN)), K(2, vector<int>(n * n));
    int t = 0;
    while(1) {
        t++;
        for(int i = 0; i < n; i++)
            for(int j = i + 1; j < n; j++) {
                int a = K[t % 2][i * n + j];
                K[(t + 1) % 2][i * n + j] = a;
                sum[i][j] = INT_MIN;
                for(int k = a + 1; k < n; k++) {
                    int X = (x[a][i] - x[a][j + 1]) + (x[k][i] - x[k][j + 1]);
                    int Y = (y[a + 1][i] - y[k][i]) + (y[a + 1][j] - y[k][j]);
                    if(sum[i][j] < X + Y) {
                        sum[i][j] = X + Y;
                        K[(t + 1) % 2][i * n + j] = k;
                    }
                    ans = max(ans, sum[i][j]);
                }
            }

        // Check for optimization completion
        int f = 1;
        for(int i = 0; i < n; i++)
            for(int j = i + 1; j < n; j++)
                for(int k = K[t % 2][i * n + j] + 1; k < K[(t + 1) % 2][i * n + j]; k++) {
                    f = 0;
                    int X = (x[k][i + 1] - x[k][j]) - (x[k - 1][i] - x[k - 1][j + 1]);
                    sum[i][j] += X;
                    ans = max(ans, sum[i][j]);
                }
        if(f) break;
    }

    printf("%d\n", ans);
}

int main() {
    int n;
    scanf("%d", &n);
    vector<vector<int>> y(n, vector<int>(n)), x(n, vector<int>(n));
    for(int i = 0; i < n; i++)
        for(int j = 0; j < n; j++) {
            scanf("%d", &y[i][j]);
        }
    calculateMax(n, y, x);
    return 0;
}

